<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'media']); ?>
<section class="studio-page studio-media-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">ARQUIVOS</p><h2>Biblioteca de mídia</h2><p>Visualize, filtre e gerencie as imagens usadas pelo sistema.</p></div><div class="studio-actions"><details class="studio-upload-popover"><summary class="studio-btn primary"><?= studio_icon('upload') ?> Enviar imagem</summary><form method="post" enctype="multipart/form-data"><?= $this->csrf() ?><input type="hidden" name="action" value="upload"><label for="image">JPG, PNG, GIF ou WebP, até 8 MB</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required><button class="studio-btn primary">Enviar arquivo</button></form></details><span class="studio-btn"><?= count($files) ?> arquivos</span></div></header>
<form class="studio-media-toolbar" method="get"><label><?= studio_icon('search') ?><input name="q" value="<?= $this->e($search) ?>" placeholder="Buscar por nome ou texto alternativo"></label><button class="studio-btn" type="submit">Filtrar</button><?php if($search!==''):?><a class="studio-btn" href="/admin/media">Limpar</a><?php endif;?></form>
<div class="studio-media-grid"><?php if($files===[]):?><p class="studio-panel studio-empty">Nenhuma imagem enviada.</p><?php endif;?><?php foreach($files as $file):?><article class="studio-panel studio-media-card"><div class="studio-media-preview"><img src="/admin/media/file/<?= (int)$file['id'] ?>" alt="<?= $this->e($file['alt_text']??'') ?>"><span><?= (int)$file['usage_count']>0?'Em uso':'Livre' ?></span></div><div class="studio-media-meta"><h3><?= $this->e($file['name']) ?></h3><p><?= (int)$file['width'] ?> × <?= (int)$file['height'] ?> px</p></div><details class="studio-media-manage"><summary>Gerenciar imagem</summary><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="metadata"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><label><span>Texto alternativo</span><input name="alt_text" maxlength="255" value="<?= $this->e($file['alt_text']??'') ?>" placeholder="Descreva a imagem"></label><button>Salvar descrição</button></form><form class="studio-crop-form" method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="crop"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><?php foreach(['crop_x'=>'X','crop_y'=>'Y','crop_width'=>'Largura','crop_height'=>'Altura'] as $name=>$label):?><label><span><?= $label ?></span><input type="number" name="<?= $name ?>" min="0" value="<?= str_contains($name,'width')?(int)$file['width']:(str_contains($name,'height')?(int)$file['height']:0) ?>" required></label><?php endforeach;?><button>Criar cópia recortada</button></form><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><button class="studio-danger-button"<?= (int)$file['usage_count']>0?' disabled title="Imagem em uso"':'' ?> onclick="return confirm('Excluir esta imagem?')"><?= studio_icon('trash') ?> Excluir</button></form></details></article><?php endforeach;?></div></section>
